import{_ as n,C as s,o as e,c as d,j as i,E as t,a as l,a2 as r}from"./chunks/framework.C21TwvGF.js";const j=JSON.parse(`{"title":"7-dars (Mentor). Ma’lumotlarni tozalash (Data Cleaning) va transformatsiya","description":"","frontmatter":{"title":"7-dars (Mentor). Ma’lumotlarni tozalash (Data Cleaning) va transformatsiya","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"week":{"n":3,"link":"/mentor/9-sinf-bi/hafta-03/"},"g":7,"title":"Ma’lumotlarni tozalash (Data Cleaning) va transformatsiya","lead":"Tahlilchining eng muhim mahorati: ortiqcha bo'shliqlar, xato formatlar va dublikatlardan xoli, 100% toza va sifatli ma'lumotlar to'plamini yaratish san'ati.","slide":"/slaydlar/9-sinf-bi/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-bi/hafta-03/dars-1-test.html","student_link":"/9-sinf-bi/hafta-03/dars-1","tabs":[{"g":7,"link":"/mentor/9-sinf-bi/hafta-03/dars-1","current":true},{"g":8,"link":"/mentor/9-sinf-bi/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/9-sinf-bi/hafta-03/dars-3","current":false}],"prev":null,"next":{"g":8,"title":"Pivot jadvallar (PivotTable) va ma'lumotlar vizualizatsiyasi","link":"/mentor/9-sinf-bi/hafta-03/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-03/dars-1.md","filePath":"mentor/9-sinf-bi/hafta-03/dars-1.md"}`),h={name:"mentor/9-sinf-bi/hafta-03/dars-1.md"},u={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},c={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},q={class:"blk"},b={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},k={class:"blk"},f={id:"tezkor-nazorat-savollari",tabindex:"-1"},y={class:"blk"},v={id:"uyga-vazifa",tabindex:"-1"};function p(z,a,_,x,T,C){const o=s("Icon");return e(),d("div",null,[i("div",u,[i("h2",m,[t(o,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga ma’lumotlarni tozalash (Data Cleaning) tushunchasi, uning ma&#39;lumotlar sifatidagi o&#39;rni, Excel matn funksiyalari (<code>TRIM</code>, <code>CLEAN</code>, <code>PROPER</code>), <code>Text-to-Columns</code> va <code>Flash Fill</code> (Ctrl+E) vositalari, dublikatlarni o&#39;chirish hamda Power Query muhitida birlamchi transformatsiya amallarini bajarishni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar iflos va tartibsiz ma&#39;lumotlardagi xatoliklarni aniqlay oladi; ortiqcha bo&#39;shliqlarni tozalash, matn registri va formatlarni to&#39;g&#39;rilashni biladi; bitta ustundagi to&#39;liq ismni yoki manzilni alohida ustunlarga ajrata oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan haftani takrorlash: 10 daqiqa</li><li>Yangi mavzu: Data Cleaning va Excel matn vositalari: 20 daqiqa</li><li>Text-to-Columns, Flash Fill va dublikatlar: 25 daqiqa</li><li>Power Query orqali tozalash amaliyoti: 15 daqiqa</li><li>Nazorat savollari va xulosa: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",c,[i("h2",g,[t(o,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-ma-lumotlarni-tozalash-data-cleaning-nima" tabindex="-1">1. Ma’lumotlarni tozalash (Data Cleaning) nima? <a class="header-anchor" href="#_1-ma-lumotlarni-tozalash-data-cleaning-nima" aria-label="Permalink to &quot;1. Ma’lumotlarni tozalash (Data Cleaning) nima?&quot;">​</a></h3><p>Data Cleaning — bu tahlilga tayyor bo&#39;lmagan xom ma&#39;lumotlar to&#39;plamidagi xatoliklar, noaniqliklar, takroriy yozuvlar (dublikatlar), ortiqcha bo&#39;sh joylar va noto&#39;g&#39;ri formatlarni aniqlash hamda ularni to&#39;g&#39;rilash jarayonidir. Tahlilchilar o&#39;z vaqtlarining 70-80 foizini aynan ma&#39;lumotlarni tozalashga sarflaydilar. Chunki <strong>GIGO (Garbage In, Garbage Out)</strong> qoidasiga ko&#39;ra, xato ma&#39;lumot asosida qabul qilingan har qanday strategik qaror korxona uchun katta zarar keltiradi.</p><h3 id="_2-keng-tarqalgan-ma-lumot-nuqsonlari-va-ularning-yechimi" tabindex="-1">2. Keng tarqalgan ma&#39;lumot nuqsonlari va ularning yechimi <a class="header-anchor" href="#_2-keng-tarqalgan-ma-lumot-nuqsonlari-va-ularning-yechimi" aria-label="Permalink to &quot;2. Keng tarqalgan ma&#39;lumot nuqsonlari va ularning yechimi&quot;">​</a></h3><ol><li><strong>Ortiqcha bo&#39;shliqlar (Extra spaces):</strong><ul><li>So&#39;zlar orasida 2-3 tadan bo&#39;sh joy bo&#39;lishi yoki so&#39;z oxirida bo&#39;shliq qolib ketishi kompyuter uchun turli xil so&#39;zdek tuyuladi (<code>&quot;Olma &quot;</code> $\\neq$ <code>&quot;Olma&quot;</code>).</li><li>Yechim: <code>=TRIM(A2)</code> funksiyasi so&#39;zlar orasidagi bittadan tashqari barcha ortiqcha bo&#39;shliqlarni olib tashlaydi.</li></ul></li><li><strong>Matn registri (Katta-kichik harflar):</strong><ul><li>Birov <code>&quot;toshkent&quot;</code>, birov <code>&quot;TOSHKENT&quot;</code>, boshqasi esa <code>&quot;Toshkent&quot;</code> deb kiritgan.</li><li>Yechim: <code>=PROPER(A2)</code> har bir so&#39;zning bosh harfini kattaga, qolganlarini kichikka aylantiradi.</li></ul></li><li><strong>Takroriy yozuvlar (Duplicates):</strong><ul><li>Tizimda bir xil xaridor yoki buyurtma ikki marta ro&#39;yxatga olingan.</li><li>Yechim: <code>Data &gt; Remove Duplicates</code> vositasi orqali barcha dublikat qatorlar bir zumda o&#39;chiriladi.</li></ul></li></ol><h3 id="_3-matnni-ustunlarga-ajratish-text-to-columns-va-flash-fill" tabindex="-1">3. Matnni ustunlarga ajratish: Text-to-Columns va Flash Fill <a class="header-anchor" href="#_3-matnni-ustunlarga-ajratish-text-to-columns-va-flash-fill" aria-label="Permalink to &quot;3. Matnni ustunlarga ajratish: Text-to-Columns va Flash Fill&quot;">​</a></h3><ul><li><strong>Text-to-Columns (Matnni ustunlarga bo&#39;lish):</strong><ul><li>Agar bitta katakda <code>&quot;Anvar Qodirov, Toshkent&quot;</code> kabi ma&#39;lumot bo&#39;lsa, <code>Data &gt; Text to Columns</code> orqali uni ajratuvchi belgi (vergul, bo&#39;sh joy yoki nuqta-vergul) asosida alohida ustunlarga bo&#39;lish mumkin.</li></ul></li><li><strong>Flash Fill (Ctrl + E):</strong><ul><li>Excelning eng aqlli sun&#39;iy intellekt vositasi. Siz yangi ustunning 1-qatoriga namunani yozasiz (masalan, to&#39;liq ismdan faqat ismni ajratib yozasiz) va <code>Ctrl + E</code> tugmasini bossangiz, Excel qolgan yuzlab qatorlarni namuna asosida o&#39;zi to&#39;ldirib beradi!</li></ul></li></ul><h3 id="_4-power-query-orqali-professional-tozalash" tabindex="-1">4. Power Query orqali professional tozalash <a class="header-anchor" href="#_4-power-query-orqali-professional-tozalash" aria-label="Permalink to &quot;4. Power Query orqali professional tozalash&quot;">​</a></h3><p>Power Query — Excel va Power BI ning rasmiy ETL (Extract, Transform, Load) vositasi bo&#39;lib, barcha tozalash qadamlarini (Applied Steps) xotirada saqlaydi:</p><ul><li><code>Transform &gt; Format &gt; Trim &amp; Clean</code></li><li><code>Transform &gt; Split Column by Delimiter</code></li><li><code>Home &gt; Remove Rows &gt; Remove Duplicates</code> (Katta-kichik harfni inobatga olmaslik uchun: <code>Comparer.OrdinalIgnoreCase</code>)</li><li><code>Transform &gt; Replace Values</code> (<code>null</code> qiymatlarni <code>0</code> yoki <code>&quot;Noma&#39;lum&quot;</code> bilan almashtirish). Manba yangilansa, <code>Refresh</code> tugmasi bilan butun tozalash jarayoni avtomatik qayta bajariladi.</li></ul><hr>',10))]),i("div",q,[i("h2",b,[t(o,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-trim-va-proper-funksiyalarini-qo-llash-oson" tabindex="-1">1-topshiriq. TRIM va PROPER funksiyalarini qo&#39;llash (oson) <a class="header-anchor" href="#_1-topshiriq-trim-va-proper-funksiyalarini-qo-llash-oson" aria-label="Permalink to &quot;1-topshiriq. TRIM va PROPER funksiyalarini qo&#39;llash (oson)&quot;">​</a></h3><p>Jadvalda ismlar quyidagicha xato kiritilgan:</p><ul><li>A2: <code>&quot; alisher navoiy &quot;</code></li><li>A3: <code>&quot;BOBUR MIRZO &quot;</code> Yangi ustunda formulalar orqali ushbu ismlarni ortiqcha bo&#39;shliqlarsiz va to&#39;g&#39;ri bosh harflar bilan ko&#39;rinishga keltiring.</li></ul><p><strong>Yechim:</strong> Formula <code>B2</code> katagiga yoziladi: <code>=PROPER(TRIM(A2))</code> Natija:</p><ul><li>B2: <code>&quot;Alisher Navoiy&quot;</code></li><li>B3: <code>&quot;Bobur Mirzo&quot;</code></li></ul><h3 id="_2-topshiriq-flash-fill-ctrl-e-bilan-telefon-kodlarini-ajratish-o-rta" tabindex="-1">2-topshiriq. Flash Fill (Ctrl + E) bilan telefon kodlarini ajratish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-flash-fill-ctrl-e-bilan-telefon-kodlarini-ajratish-o-rta" aria-label="Permalink to &quot;2-topshiriq. Flash Fill (Ctrl + E) bilan telefon kodlarini ajratish (o&#39;rta)&quot;">​</a></h3><p>A ustunida telefon raqamlari yozilgan: <code>+998901234567</code>, <code>+998935554433</code>, <code>+998971112233</code>.</p><ol><li>B ustuniga <code>Kompaniya kodi</code> sarlavhasini yozing.</li><li>B2 katagiga namuna sifatida birinchi raqamning kodini: <code>90</code> deb yozing va Enter bosing.</li><li><code>Ctrl + E</code> tugmasini bosing va natijani tekshiring.</li></ol><p><strong>Yechim:</strong><code>Ctrl + E</code> bosilganda Excel naqshni darhol ilg&#39;aydi va B3 ga <code>93</code>, B4 ga <code>97</code> qiymatlarini avtomatik to&#39;ldirib beradi.</p><h3 id="_3-topshiriq-text-to-columns-va-bo-sh-qiymatlarni-tozalash-qiyin" tabindex="-1">3-topshiriq. Text-to-Columns va Bo&#39;sh qiymatlarni tozalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-text-to-columns-va-bo-sh-qiymatlarni-tozalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Text-to-Columns va Bo&#39;sh qiymatlarni tozalash (qiyin)&quot;">​</a></h3><p>Mijozlar to&#39;plamida manzil va to&#39;lov quyidagicha aralash kelgan: <code>&quot;Toshkent - 150000; Samarqand - ; Buxoro - 85000&quot;</code>.</p><ol><li>Ma&#39;lumotlarni shahar va summa bo&#39;yicha alohida ustunlarga ajrating.</li><li>Bo&#39;sh summalarni (Samarqand filialidagi to&#39;lov yo&#39;q katakni) <code>Find &amp; Replace</code> orqali <code>0</code> raqamiga almashtiring.</li><li>Takroriy shaharlar bo&#39;lsa, <code>Remove Duplicates</code> orqali tozalang.</li></ol><p><strong>Yechim:</strong></p><ol><li>Diapazon tanlanib, <code>Data &gt; Text to Columns</code> orqali Delimiter: <code>-</code> (defis) tanlanadi va 2 ta ustunga bo&#39;linadi.</li><li>Summa ustunidagi bo&#39;sh kataklar belgilanadi yoki <code>Ctrl + H</code> (Find &amp; Replace) orqali bo&#39;sh joylar <code>0</code> ga almashtiriladi.</li><li><code>Data &gt; Remove Duplicates</code> bosilib, Shahar ustuni bo&#39;yicha dublikatlar o&#39;chiriladi.</li></ol><hr>',15))]),i("div",k,[i("h2",f,[t(o,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li><code>TRIM</code> funksiyasi qanday bo&#39;shliqlarni olib tashlaydi va qaysilarini qoldiradi? <ul><li><em>Javob:</em> So&#39;z boshidagi, oxiridagi va so&#39;zlar orasidagi ortiqcha bo&#39;shliqlarni olib tashlaydi, faqat bitta bo&#39;shliqni qoldiradi.</li></ul></li><li><code>Flash Fill</code> (Tezkor to&#39;ldirish) qaysi klaviatura birikmasi bilan ishga tushadi? <ul><li><em>Javob:</em> <code>Ctrl + E</code>.</li></ul></li><li>Power Query&#39;da bajarilgan tozalash amallarining an&#39;anaviy Exceldan asosiy afzalligi nima? <ul><li><em>Javob:</em> Barcha amallar <code>Applied Steps</code> bo&#39;lib saqlanadi va yangi ma&#39;lumot kelganda bitta <code>Refresh</code> tugmasi bilan butun tozalash avtomatik takrorlanadi.</li></ul></li></ol><hr>",2))]),i("div",y,[i("h2",v,[t(o,{name:"house"}),a[12]||(a[12]=l(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,[l("Excelda 8 nafar insonning ismi, familiyasi va yashash shahri aralash yozilgan jadval tuzing (masalan: "),i("code",null,'"jasur olimov, toshkent"'),l("). Formulalar yoki "),i("code",null,"Flash Fill"),l(" yordamida ismni, familiyani va shaharni 3 ta alohida toza ustunga ajratib, bosh harflarini to'g'rilang.")],-1))])])}const E=n(h,[["render",p]]);export{j as __pageData,E as default};
